  "help.paycheckFlow": "দৰমহা বিয়োগ কৰি ফিক্সড বিল (ভাড়া, EMIs, বীমা) বিয়োগ কৰি নমনীয় বিল (কাৰ্ড, চাব)। বাকী আছে বিনামূলীয়া নগদ ধন।",
  "help.lendingFlexible": "নমনীয়: যিকোনো সময়তে যিকোনো পেমেণ্ট ৰেকৰ্ড কৰক — আংশিক বা সম্পূৰ্ণ। মাহেকীয়া: কিস্তিৰ সময়সূচী অনুসৰণ কৰে। এককালীন ধন: এটা লক্ষ্য তাৰিখ, পাৰিলে ধন দিয়ক।",
  "help.pressureWeight": "প্ৰতিটো বিলৰ পৰা মাহেকীয়া অনুমান: পৰিমাণ ÷ পুনৰাবৃত্তিৰ ব্যৱধান (যেনে ₹3,000 ত্ৰিমাসিক → ₹1,000/মাহ)। এককালীন বিলত সম্পূৰ্ণ ধন ব্যৱহাৰ কৰা হয়। কেৱল আপোনাৰ সংৰক্ষিত বিল — একোৱেই প্ৰি-ফিল কৰা নহয়।",
  "help.openBalance": "বৰ্তমান সক্ৰিয় বিলত এতিয়াও ঋণী মুঠ (মাহেকীয়া বোজাৰ সৈতে একে নহয়)।",
  "help.dueThisMonth": "চলিত কেলেণ্ডাৰ মাহত নিৰ্ধাৰিত তাৰিখ থকা বিল যিবোৰ এতিয়াও সম্পূৰ্ণৰূপে পৰিশোধ কৰা হোৱা নাই।",
  "help.freeAfterDues": "আয় বিয়োগ কৰি পুনৰাবৃত্তিমূলক আৰু সক্ৰিয় বিলৰ পৰা আনুমানিক মাহিলী বাবদ ধন।",
  "help.dueHeatmap": "অহা চাৰি সপ্তাহৰ প্ৰতিটোতে কিমান বিল পৰিশোধ কৰিবলগীয়া হয় আৰু ইয়াৰ মুঠ ধনৰাশি।",
  "help.debtTrend": "আমাৰ হাতত স্নেপশ্বট থকা আটাইতকৈ পুৰণি আৰু নতুন মাহৰ মাজত মুঠ মুকলি ভাৰসাম্যৰ পৰিৱৰ্তন।",
  "help.chitInstallments": "বেছিভাগ ডাঙৰ চিটে সমান মাহিলী শ্বেয়াৰ (মূল্য ÷ মাহ) ব্যৱহাৰ কৰে। কিছুমান গোটে হ্ৰাস পোৱা কিস্তি ব্যৱহাৰ কৰে (আগতীয়াকৈ উচ্চ, পিছত কম)। আপোনাৰ গোটৰ সৈতে মিল থকা ধৰণটো বাছি লওক।",
  "help.chitMonthsPaid": "ইতিমধ্যে কিমান কিস্তি দিলে। যদি আপুনি ৪৬ টকা দিছিল তেন্তে আপুনি এতিয়া ৪৭ মাহত আছে। ইয়াৰ দ্বাৰা প্ৰাপ্য ধন আৰু মাহৰ সংখ্যা নিৰ্ধাৰণ কৰা হয়।",
  "help.chitPayoutReceived": "চিট লোৱাৰ সময়ত পোৱা প্ৰকৃত নগদ ধন (যেনে ₹4,43,000)। আমি ইয়াৰ পৰা নিলামৰ ৰেহাইৰ কাম উলিয়াওঁ — আপুনি ৰেহাই অনুমান কৰাৰ প্ৰয়োজন নাই।",
  "help.chitForeman": "অৰ্গেনাইজাৰ কমিচন, প্ৰায়ে চিটৰ মূল্যৰ প্ৰায় ৫%, টকা লাভ কৰিলে পাত্ৰৰ পৰা লোৱা।",
  "help.chitDiscount": "নিলামত আপুনি সম্পূৰ্ণ চিট মূল্যতকৈ কম গ্ৰহণ কৰে — এই ৰেহাই অন্য সদস্যসকলৰ সৈতে ভাগ কৰা হয়। আপুনি কেতিয়াও সম্পূৰ্ণ চিটৰ ধন নগদ ধনত নাপায়।",
  "help.chitAdvisor": "আপুনি চিট ল'ব পৰা মাহবোৰৰ তুলনা কৰে: আনুমানিক ৰেহাই, ফৰমেনৰ পিছত পেআউট, সেই মাহত আপোনাৰ আন বিল, আৰু আপুনি গ্ৰহণ কৰিবলৈ ইচ্ছুক সৰ্বোচ্চ লোকচান।",
  "help.chitMaxLoss": "আমি আপোনাৰ আয়, মাহিলী বাবদ ধন, মুকলি ঋণ, অতিৰিক্ত বিল, আৰু সঞ্চয়ৰ পৰা সৰ্বোচ্চ লোকচানৰ পৰামৰ্শ দিওঁ — এটা নিৰ্দিষ্ট % নহয়। সোনকালে গ্ৰহণ কৰিলে প্ৰায়ে ইয়াক অতিক্ৰম কৰা হয়; পিছৰ মাহত সাধাৰণতে কম খৰচ হয়।",
  "help.loanExtraTiming": "আগন্তুক মাহবোৰ দেখুৱায়: যেতিয়া অন্য বিলবোৰ লঘু হয় যাতে আপুনি এই ঋণত অতিৰিক্ত ধন দিব পাৰে, আৰু গধুৰ মাহবোৰ যেতিয়া আপুনি নূন্যতম স্তৰত থিয় দিব লাগে।",
  "help.incomeEntryBasis": "টেক-হোম কৰ, PF, আৰু নিৰ্দিষ্ট কৰ্তনৰ পিছত আপোনাৰ বেংকত কি অৱতৰণ কৰে তাৰ সৈতে মিল খায় — চাপ আৰু বিনামূলীয়া নগদ ধনৰ গণিতৰ বাবে সৰ্বোত্তম। আপুনি প্ৰৱেশ কৰা প্ৰতিটো সংখ্যা কৰ-পূৰ্ব হ’লেহে গ্ৰছ উপযোগী; যদি টেক-হোম আয় মুঠতকৈ কম হয় তেন্তে বিনামূলীয়া নগদ ধন আপোনাৰ প্ৰকৃত বেংক বেলেঞ্চতকৈ কম দেখা যাব পাৰে।",
  "help.householdPayerBillTag": "পৰিয়ালৰ ধৰণৰ বাবে বৈকল্পিক: কোনে ধন দিয়ে টেগ কৰক যাতে ঘৰৰ নাড়ীয়ে বিভক্ত দায়িত্বৰ বৰ্ণনা কৰিব পাৰে। মুঠ আৰু চাপৰ গণিত একেই থাকে।",
