  "guide.setup.subtitle": "আপুনি Perovo (দৰমহাযুক্ত বা ঘৰুৱা) কেনেকৈ ব্যৱহাৰ কৰে পুনৰীক্ষণ কৰক আৰু আয়ৰ মূল কথাবোৰ আপডেট কৰক। আপোনাৰ বিলবোৰ যিদৰে আছে তেনেদৰেই থাকে।",
