  "guide.household.roomsLabel": "কোঠাবোৰে কেনেকৈ কাম কৰে",
  "guide.household.inviteTitle": "আপোনাৰ পৰিয়ালৰ আমন্ত্ৰণ ক'ড",
  "guide.household.inviteText": "এই ৬ আখৰৰ ক'ডটো পৰিয়ালৰ সদস্যসকলৰ সৈতে শ্বেয়াৰ কৰক। সিহঁতে Perovo ত চাইন ইন কৰে, Profile ত পৰিয়াল ধৰণ অন কৰে, আৰু আপোনাৰ কোঠাত যোগদান কৰিবলে এই ক'ড সুমুৱায়।",
  "guide.household.shareTitle": "আপুনি যি শ্বেয়াৰ কৰে তাক নিয়ন্ত্ৰণ কৰক",
  "guide.household.shareText": "পৰিয়ালৰ সদস্যসকলে কি চাব পাৰে সেইটো আপুনি সিদ্ধান্ত লয়। আপোনাৰ দৈনন্দিন খৰচ আনক চাবলৈ শ্বেয়াৰ খৰচ টগল কৰক। আপোনাৰ প্ৰতিশ্ৰুতি তালিকা অংশীদাৰী কৰিবলৈ বিলৰ নাম টগল কৰক।",
  "guide.household.outlookTitle": "ঘৰুৱা দৃষ্টিভংগী",
  "guide.household.outlookText": "আপোনাৰ পৰিয়ালৰ বাবে সংযুক্ত আৰ্থিক স্বাস্থ্য — জৰুৰীকালীন পুঁজিৰ কভাৰেজ, ভাগ কৰা হেঁচা, আৰু লক্ষ্য। যিকোনো সদস্যৰ তথ্য সলনি হ'লে আপডেট কৰা হয়।",
  "guide.pulse.label": "এয়া কি?",
  "guide.pulse.pressureTitle": "চাপৰ স্ক’ৰ",
  "guide.pulse.pressureText": "আপোনাৰ আৰ্থিক চাপৰ স্ক’ৰে (০–১০০) আপোনাৰ আয়ৰ কিমানখিনি নিৰ্দিষ্ট বাধ্যবাধকতালৈ যায় জুখিব পাৰে। ৪৫ বছৰৰ তলত স্বাস্থ্যকৰ। ৭০ৰ ওপৰত মানে আপোনাৰ বাধ্যবাধকতা গধুৰ।",
  "guide.pulse.freeCashTitle": "Free নগদ ধন",
  "guide.pulse.freeCashText": "এই মাহত আপোনাৰ সকলো কমিটমেণ্ট পেমেণ্টৰ পিছত টকা বাকী আছে। এইটোৱেই আপুনি আচলতে খৰচ কৰিব লাগিব, সঞ্চয় কৰিব লাগিব বা বিনিয়োগ কৰিব লাগিব।",
  "guide.pulse.survivalTitle": "ছাৰভাইভেল ৰাণৱে",
  "guide.pulse.survivalText": "আজি যদি আপুনি সকলো আয় হেৰুৱাই পেলায়, তেন্তে আপুনি সঞ্চয়ৰ পৰা আপোনাৰ বাধ্যবাধকতা কিমান মাহত আদায় কৰিব পাৰিব? ৬+ মাহ লক্ষ্য।",
