  "notifications.enabledOk": "ব্ৰাউজাৰ সতৰ্কবাণীসমূহ সামৰ্থবান কৰা হৈছে। এপ বন্ধ হ’লে সতৰ্কবাণীৰ বাবে হোম স্ক্ৰীণত এপ যোগ কৰক।",
