  "notifications.deniedErrNative": "Android ছেটিংছত ব্লক কৰা হৈছে। ছেটিংছ → এপ্প্ সমূহ → পেৰ'ভ' → জাননীসমূহ খোলক আৰু সতৰ্কবাণীসমূহৰ অনুমতি দিয়ক, তাৰ পিছত পুনৰ চেষ্টা কৰক।",
  "notifications.testDeniedNative": "অনুমতি অস্বীকাৰ কৰা হৈছে। Android সংহতিসমূহত জাননীসমূহৰ অনুমতি দিয়ক, তাৰ পিছত পুনৰ চেষ্টা কৰক।",
  "notifications.nativeHint": "ট্ৰে সতৰ্কবাণীসমূহে Android জাননীসমূহ ব্যৱহাৰ কৰে। এই পৰ্দাত বিল সোঁৱৰাই দিয়াসমূহ অন ৰাখক। ডেউ আৰু অভাৰডু বিলসমূহে এপটো বন্ধ হ’লেও অৱগত কৰে।",
  "notifications.deniedErr": "ব্ৰাউজাৰ ছেটিংছত ব্লক কৰা হৈছে। এই চাইটৰ বাবে জাননীসমূহৰ অনুমতি দিয়ক, তাৰ পিছত পুনৰ চেষ্টা কৰক।",
  "notifications.testOk": "আপোনাৰ চিস্টেম অধিসূচনা পেনেল আৰু ইন-এপ বেললৈ পঠোৱা হৈছে। ফোনত তললৈ চুইপ কৰি চাব।",
