  "notifications.testUnsupported": "এই ব্ৰাউজাৰে জাননীসমূহ সমৰ্থন নকৰে।",
  "notifications.testFail": "সতৰ্কতা দেখুৱাব পৰা নগ'ল। এপটো ইনষ্টল কৰক (হোম স্ক্ৰীণত যোগ কৰক) বা Chrome/Edge ব্যৱহাৰ কৰক।",
  "notifications.testInApp": "পৰীক্ষা সোঁৱৰাই দিয়া — এই ডিভাইচত জাননীসমূহে কাম কৰি আছে।",
  "notifications.installHint": "ট্ৰে সতৰ্কবাণীৰ বাবে: এপটো ইনষ্টল কৰক (হোম স্ক্ৰীণত যোগ কৰক), জাননীসমূহৰ অনুমতি দিয়ক, আৰু সোঁৱৰাই দিয়াসমূহ অন ৰাখক। আপুনি এপটো এৰি যোৱাৰ সময়ত বা প্ৰতি কেইঘণ্টামানৰ মূৰে মূৰে (Android/Chrome) ডেউ আৰু অভাৰডু বিলসমূহে অৱগত কৰে। iPhone ৰ বাবে হোম-স্ক্ৰীণ এপ আইকনৰ প্ৰয়োজন — Safari টেবসমূহে কেৱল পটভূমি-জাননী দিব নোৱাৰে।",
