  "privacy.whereBody": "প্ৰধানকৈ আপোনাৰ ডিভাইচত (localStorage)। বৈকল্পিকভাৱে Supabase ত (জিৰণি লোৱাৰ সময়ত ইনক্ৰিপ্ট কৰা, প্ৰতিজন ব্যৱহাৰকাৰীৰ বাবে পৃথক) যেতিয়া ক্লাউড সিঙ্ক সামৰ্থবান কৰা হয়।",
  "privacy.notTitle": "আমি কি নকৰো",
  "privacy.notBody": "আমি আপোনাৰ ডাটা বিক্ৰী নকৰো। আমি ক্ৰেডিট ব্যুৰোৰ সৈতে শ্বেয়াৰ নকৰো। আমি বিজ্ঞাপনৰ বাবে ডাটা ব্যৱহাৰ নকৰো। Razorpay-এ পেমেন্ট নিয়ন্ত্ৰণ কৰে — Perovo-এ আপোনাৰ কাৰ্ডৰ বিৱৰণ কেতিয়াও দেখা নাপায়।",
