  "insight.pressure-down": "আপুনি আগৰ মাহৰ স্নেপশ্বটৰ তুলনাত মুকলি বিলৰ চাপ হ্ৰাস কৰিলে।",
  "insight.multi-overdue": "{count} বস্তুবোৰ অতিক্ৰম কৰা হৈছে — প্ৰথমে সিহতক ক্লিয়াৰ কৰিলে সাধাৰণতে চাপ অতি প্ৰত্যক্ষভাৱে হ্ৰাস পায়।",
  "insight.paying-habit": "আপুনি এই মাহত পেমেণ্টত {amount} ৰেকৰ্ড কৰিছে — সামঞ্জস্যপূৰ্ণ পেমেণ্টে বিত্তীয় ৰাণৱে উন্নত কৰে।",
  "insight.overlap-week": "এই সপ্তাহত আপোনাৰ {count} বাবদ (≈{total} মুঠ) আছে—সম্ভৱ হ'লে পেমেণ্টসমূহ ষ্টেগাৰ কৰক।",
  "insight.forecast-crunch-negative": "আপুনি {month} ৰ ওচৰত ঋণাত্মক বিনামূলীয়া নগদ ধনৰ সন্মুখীন হ’ব পাৰে (বাবেই ধন সেই মাহৰ আয়তকৈ বেছি)।",
