  "insight.subs-yearly": "আপোনাৰ চাবস্ক্ৰিপচনসমূহৰ মূল্য বৰ্তমানৰ হাৰত প্ৰায় {amount}/বছৰ হ'ব পাৰে।",
  "insight.emi-pct": "EMIs আপোনাৰ উল্লেখিত মাহিলী আয়ৰ প্ৰায় {percent}% ব্যৱহাৰ কৰে — নতুন ঋণ লোৱাৰ ক্ষেত্ৰত সাৱধানতা অৱলম্বন কৰক।",
  "insight.txn-delivery-dependency": "এই সপ্তাহত খাদ্য ডেলিভাৰীৰ ব্যয়ৰ বৃহৎ অংশ — নিৰ্ভৰশীলতা নিৰৱে বৃদ্ধি হ’ব পাৰে।",
