  "insight.txn-small-leaks": "এই সপ্তাহত কেইবাটাও সৰু সৰু ক্ৰয়ৰ ফলত হয়তো লাহে লাহে মাহেকীয়া নমনীয়তা হ্ৰাস পাইছে।",
