  "insight.txn-recurring-growth-high": "পুনৰাবৃত্তিমূলক বৈকল্পিক খৰচ লাহে লাহে বৃদ্ধি পাইছে — সৰু সৰু পুনৰাবৃত্তিই নমনীয়তা হ্ৰাস কৰিব পাৰে।",
  "insight.txn-recurring-growth": "যোৱা কেইমাহমানৰ ভিতৰত পুনৰাবৃত্তিমূলক বাধ্যবাধকতাসমূহ প্ৰায় {percent}% বৃদ্ধি পাইছে।",
  "insight.txn-under-pressure": "ইতিমধ্যে বাধ্যবাধকতাৰ চাপ বৃদ্ধি পোৱাৰ সময়তে বিবেচনাধীন দৈনিক ব্যয় অব্যাহত থাকে।",
